export function validateWorkflowAdmissionRecord(record) {
    if (!record)
        return "Paused terminal transitions require trusted admission";
    const validValue = record.expected === null
        || (typeof record.expected === "string" && record.expected.length <= 1_024)
        || typeof record.expected === "boolean"
        || (typeof record.expected === "number" && Number.isFinite(record.expected));
    if ((record.claimClass !== "environmental" && record.claimClass !== "user_authority")
        || !record.provider || record.provider.length > 64
        || !record.subject || record.subject.length > 256
        || !record.fact || record.fact.length > 64
        || !validValue
        || !Array.isArray(record.observations) || record.observations.length < 1 || record.observations.length > 8
        || record.observations.some((observation) => typeof observation !== "string" || !observation || observation.length > 129)
        || !Number.isFinite(record.decidedAt)) {
        return "Paused terminal transition admission is malformed";
    }
    return undefined;
}
export function getActiveWorkflowStateLoop(run) {
    return run.definition.states[run.currentState]?.loop;
}
export function atWorkflowStateFireLimit(run) {
    const loop = getActiveWorkflowStateLoop(run);
    return loop?.maxFires !== undefined && (run.stateFireCounts?.[run.currentState] ?? 0) >= loop.maxFires;
}
export function getWorkflowOutcomeAvailability(run) {
    const state = run.definition.states[run.currentState];
    const available = [];
    const unavailable = [];
    for (const [outcome, targetState] of Object.entries(state?.on ?? {})) {
        const target = run.definition.states[targetState];
        const nextAttempt = (run.attemptsByState[targetState] ?? 0) + 1;
        if (targetState === run.currentState && target?.maxAttempts === undefined) {
            unavailable.push({ outcome, targetState, reason: "unbounded_self_loop" });
        }
        else if (target?.maxAttempts !== undefined && nextAttempt > target.maxAttempts) {
            unavailable.push({ outcome, targetState, maxAttempts: target.maxAttempts });
        }
        else {
            available.push(outcome);
        }
    }
    return { available, unavailable };
}
function createLease(actor, at) {
    if (!actor)
        return undefined;
    return {
        ownerSessionId: actor.sessionId,
        ownerRuntimeId: actor.runtimeId,
        acquiredAt: at,
        heartbeatAt: at,
        expiresAt: at + 30 * 60 * 1000,
        attempt: 1,
    };
}
function activateExecution(options) {
    return {
        id: `${options.stateId}:${options.transitionSeq}`,
        stateId: options.stateId,
        transitionSeq: options.transitionSeq,
        subject: options.task.subject,
        description: options.task.description,
        status: "active",
        createdAt: options.at,
        updatedAt: options.at,
        lease: createLease(options.actor, options.at),
    };
}
export function createWorkflowRun(definition, at, actor) {
    const initial = definition.states[definition.initialState];
    return {
        definition,
        definitionRevision: 1,
        revisionHistory: [],
        currentState: definition.initialState,
        transitionSeq: 0,
        stateEnteredAt: at,
        attemptsByState: { [definition.initialState]: 1 },
        stateFireCounts: {},
        activeExecution: initial?.task
            ? activateExecution({ stateId: definition.initialState, transitionSeq: 0, task: initial.task, at, actor })
            : undefined,
    };
}
export function isTerminalWorkflowRun(run) {
    return Boolean(run?.definition.states[run.currentState]?.terminal);
}
function validateExecutionOwnership(run, actor, at) {
    const current = run.definition.states[run.currentState];
    if (!current?.task)
        return undefined;
    const active = run.activeExecution;
    if (!active || active.stateId !== run.currentState || active.transitionSeq !== run.transitionSeq || active.status !== "active") {
        return "Workflow execution is missing or does not match the active state";
    }
    if (!active.lease)
        return "Workflow execution is unowned; claim it before transitioning";
    if (!actor)
        return "Workflow transition requires an active session runtime";
    if (active.lease.expiresAt <= at)
        return "Workflow execution lease expired; claim it before transitioning";
    if (active.lease.ownerSessionId !== actor.sessionId || active.lease.ownerRuntimeId !== actor.runtimeId) {
        return "Workflow execution is leased to another active runtime";
    }
    return undefined;
}
function resolveTarget(run, outcome) {
    const current = run.definition.states[run.currentState];
    if (!current)
        return { error: `Current state "${run.currentState}" is not defined` };
    if (current.terminal)
        return { error: `Workflow is already ${current.terminal}` };
    const target = current.on?.[outcome];
    if (!target)
        return { error: `Outcome "${outcome}" is not allowed from state "${run.currentState}"` };
    const targetState = run.definition.states[target];
    if (!targetState)
        return { error: `Transition target "${target}" is not defined` };
    if (target === run.currentState && targetState.maxAttempts === undefined) {
        return {
            error: `State "${target}" self-loop "${outcome}" is unbounded; revise it with maxAttempts before retrying`,
            failure: {
                code: "unbounded_self_loop",
                outcome,
                targetState: target,
            },
        };
    }
    const nextAttempt = (run.attemptsByState[target] ?? 0) + 1;
    if (targetState.maxAttempts !== undefined && nextAttempt > targetState.maxAttempts) {
        return {
            error: `State "${target}" has exhausted its ${targetState.maxAttempts} attempt limit`,
            failure: {
                code: "target_exhausted",
                outcome,
                targetState: target,
                maxAttempts: targetState.maxAttempts,
            },
        };
    }
    return { target, terminal: targetState.terminal };
}
function settleExecution(execution, evidence, at) {
    if (!execution)
        return undefined;
    return {
        ...execution,
        status: "completed",
        updatedAt: at,
        settledAt: at,
        evidence,
        lease: undefined,
    };
}
export function transitionWorkflowRun(run, input, at) {
    const ownershipError = validateExecutionOwnership(run, input.actor, at);
    if (ownershipError)
        return { applied: false, error: ownershipError };
    const resolved = resolveTarget(run, input.outcome);
    if (!resolved.target)
        return { applied: false, error: resolved.error ?? "Unknown workflow transition error", failure: resolved.failure };
    const target = resolved.target;
    const targetState = run.definition.states[target];
    if (!targetState)
        return { applied: false, error: `Transition target "${target}" is not defined` };
    if (targetState.terminal === "paused" || input.admission) {
        const admissionError = validateWorkflowAdmissionRecord(input.admission);
        if (admissionError)
            return { applied: false, error: admissionError };
    }
    const sequence = run.transitionSeq + 1;
    const settled = settleExecution(run.activeExecution, input.evidence, at);
    const destination = targetState.task && !targetState.terminal
        ? activateExecution({ stateId: target, transitionSeq: sequence, task: targetState.task, at })
        : undefined;
    const lastTransition = {
        from: run.currentState,
        to: target,
        outcome: input.outcome,
        evidence: input.evidence,
        admission: input.admission,
        at,
        sequence,
    };
    const nextRun = {
        ...run,
        currentState: target,
        transitionSeq: sequence,
        stateEnteredAt: at,
        attemptsByState: { ...run.attemptsByState, [target]: (run.attemptsByState[target] ?? 0) + 1 },
        stateFireCounts: run.stateFireCounts ?? {},
        activeExecution: destination,
        executionHistory: settled ? [...(run.executionHistory ?? []), settled] : run.executionHistory,
        waitingMonitor: undefined,
        lastTransition,
    };
    return { applied: true, run: nextRun, terminal: resolved.terminal };
}
